// ==============================================================================
// TUMO Chacarita — Google Apps Script for Flash Labs (December 2026)
// Bound to the enrollment spreadsheet. Deploy together with appScriptCatalogo.js
// (generated by scripts/build_labs.py), which defines CATALOGO.
// ==============================================================================

var SHEET_INSCRIPTOS = "Inscriptos";
var PADRON_SPREADSHEET_ID = "1Ft4lkvM_cz56ruRks-nHxlU_XyL-loEQVLOM4oporaU";
var PADRON_SHEET_COMPLETED = "WSH COMPLETED";
var PADRON_SHEET_ONGOING = "ONGOING WSH";
var PADRON_CACHE_KEY = "padron_v1";
var PADRON_CACHE_SECONDS = 600;
var MAX_LABS_POR_ESTUDIANTE = 2;
var DOMINIOS_CORREO = ["tumo.world", "tumo.ar"];

var COL = { fecha: 0, nombre: 1, dni: 2, correo: 3, taller: 4, dias: 5, horario: 6, disciplina: 7, comision: 8 };
var HEADERS = ["Marca temporal", "Nombre y Apellido", "DNI", "Correo TUMO", "Flash Lab", "Días", "Horario", "Disciplina", "Comisión"];

function jsonResponse(obj) {
  return ContentService.createTextOutput(JSON.stringify(obj)).setMimeType(ContentService.MimeType.JSON);
}

function normalizeDni(val) {
  return String(val || "").toUpperCase().replace(/[^A-Z0-9]/g, "");
}

function normalizeCorreo(val) {
  return String(val || "").trim().toLowerCase();
}

// "Photography I", "3D Modeling II", "3D_Modeling_I" -> "photography", "3d_modeling"
function workshopKey(name) {
  return String(name || "").trim().toLowerCase()
    .replace(/[\s_]+i+$/, "")
    .replace(/[\s_]+/g, "_");
}

function getInscriptosSheet() {
  var ss = SpreadsheetApp.getActiveSpreadsheet();
  var sheet = ss.getSheetByName(SHEET_INSCRIPTOS) || ss.getSheets()[0];
  if (sheet.getLastRow() === 0) {
    sheet.appendRow(HEADERS);
    sheet.getRange(1, 1, 1, HEADERS.length).setFontWeight("bold").setBackground("#5EB656").setFontColor("#ffffff");
  }
  return sheet;
}

function columnIndex(headerRow, name) {
  for (var i = 0; i < headerRow.length; i++) {
    if (String(headerRow[i]).trim().toLowerCase() === name.toLowerCase()) return i;
  }
  return -1;
}

// Returns { dni: ["photography", ...completed level-I workshop keys] } for every student in the padron.
// Throws when the padron cannot be read, so callers fail closed.
function loadPadron() {
  var cache = CacheService.getScriptCache();
  var cached = cache.get(PADRON_CACHE_KEY);
  if (cached) return JSON.parse(cached);

  var ss = SpreadsheetApp.openById(PADRON_SPREADSHEET_ID);
  var completed = ss.getSheetByName(PADRON_SHEET_COMPLETED);
  var ongoing = ss.getSheetByName(PADRON_SHEET_ONGOING);
  if (!completed || !ongoing) throw new Error("Padron sheets not found");

  var padron = {};
  function addStudent(dni) {
    if (dni && !padron[dni]) padron[dni] = [];
  }
  function addCompleted(dni, key) {
    addStudent(dni);
    if (dni && key && padron[dni].indexOf(key) === -1) padron[dni].push(key);
  }

  var rows = completed.getDataRange().getValues();
  var iDni = columnIndex(rows[0], "DNI");
  var iWorkshop = columnIndex(rows[0], "Workshop");
  var iPass = columnIndex(rows[0], "PassStatus");
  if (iDni < 0 || iWorkshop < 0) throw new Error("Unexpected columns in " + PADRON_SHEET_COMPLETED);
  for (var r = 1; r < rows.length; r++) {
    var rowDni = normalizeDni(rows[r][iDni]);
    var passed = iPass < 0 || String(rows[r][iPass]).trim().toLowerCase() === "completed";
    if (passed) addCompleted(rowDni, workshopKey(rows[r][iWorkshop]));
    else addStudent(rowDni);
  }

  rows = ongoing.getDataRange().getValues();
  iDni = columnIndex(rows[0], "DNI");
  if (iDni < 0) throw new Error("Unexpected columns in " + PADRON_SHEET_ONGOING);
  var levelCols = [];
  for (var c = 0; c < rows[0].length; c++) {
    if (/_I$/.test(String(rows[0][c]).trim())) levelCols.push(c);
  }
  for (r = 1; r < rows.length; r++) {
    var dni = normalizeDni(rows[r][iDni]);
    addStudent(dni);
    for (var k = 0; k < levelCols.length; k++) {
      if (/^completed/i.test(String(rows[r][levelCols[k]]).trim())) {
        addCompleted(dni, workshopKey(rows[0][levelCols[k]]));
      }
    }
  }

  if (Object.keys(padron).length === 0) throw new Error("Padron is empty");
  cache.put(PADRON_CACHE_KEY, JSON.stringify(padron), PADRON_CACHE_SECONDS);
  return padron;
}

function readParams(e) {
  if (e && e.postData && e.postData.contents) {
    try {
      return JSON.parse(e.postData.contents);
    } catch (err) {
      return (e && e.parameter) || {};
    }
  }
  return (e && e.parameter) || {};
}

/**
 * GET: enrollment counts per comision id.
 */
function doGet() {
  try {
    var data = getInscriptosSheet().getDataRange().getValues();
    var counts = {};
    for (var i = 1; i < data.length; i++) {
      var comisionId = String(data[i][COL.comision] || "").trim();
      if (comisionId) counts[comisionId] = (counts[comisionId] || 0) + 1;
    }
    return jsonResponse({ status: "ok", center: "TUMO Chacarita", counts: counts });
  } catch (err) {
    console.error(err);
    return jsonResponse({ status: "error", message: "No pudimos leer los cupos. Intentá de nuevo en unos minutos." });
  }
}

/**
 * POST: { accion: "consulta", dni, correo } lists a student's enrollments;
 * otherwise { nombre, dni, correo, comisionId } creates one.
 */
function doPost(e) {
  var params = readParams(e);
  if (params.accion === "consulta") return consultarInscripciones(params);
  return registrarInscripcion(params);
}

function consultarInscripciones(params) {
  try {
    var dni = normalizeDni(params.dni);
    var correo = normalizeCorreo(params.correo);
    if (!dni || !correo) {
      return jsonResponse({ status: "error", message: "Ingresá tu DNI y tu correo de TUMO." });
    }
    var data = getInscriptosSheet().getDataRange().getValues();
    var inscripciones = [];
    for (var i = 1; i < data.length; i++) {
      if (normalizeDni(data[i][COL.dni]) === dni && normalizeCorreo(data[i][COL.correo]) === correo) {
        inscripciones.push({
          taller: String(data[i][COL.taller]),
          dias: String(data[i][COL.dias]),
          horario: String(data[i][COL.horario])
        });
      }
    }
    return jsonResponse({ status: "ok", inscripciones: inscripciones });
  } catch (err) {
    console.error(err);
    return jsonResponse({ status: "error", message: "No pudimos consultar tus inscripciones. Intentá de nuevo en unos minutos." });
  }
}

function validarDatos(nombre, dni, correo, comision) {
  if (nombre.length < 3) return "Ingresá tu nombre y apellido completo.";
  if (!/^[A-Z0-9]{6,12}$/.test(dni)) return "Ingresá un DNI válido, sin puntos ni espacios.";
  var partes = correo.split("@");
  if (partes.length !== 2 || !partes[0] || DOMINIOS_CORREO.indexOf(partes[1]) === -1) {
    return "El correo debe ser de TUMO (@tumo.world o @tumo.ar).";
  }
  if (!comision) return "La comisión elegida no existe. Volvé a la cartelera y elegí de nuevo.";
  return "";
}

function registrarInscripcion(params) {
  var lock = LockService.getScriptLock();
  if (!lock.tryLock(15000)) {
    return jsonResponse({ status: "busy", message: "El servidor está ocupado procesando otras inscripciones. Reintentá en unos segundos." });
  }

  try {
    var nombre = String(params.nombre || "").trim();
    var dni = normalizeDni(params.dni);
    var correo = normalizeCorreo(params.correo);
    var comisionId = String(params.comisionId || "").trim();
    var comision = Object.prototype.hasOwnProperty.call(CATALOGO, comisionId) ? CATALOGO[comisionId] : null;

    var error = validarDatos(nombre, dni, correo, comision);
    if (error) return jsonResponse({ status: "error", message: error });

    var padron;
    try {
      padron = loadPadron();
    } catch (err) {
      console.error(err);
      return jsonResponse({ status: "padron_no_disponible", message: "No pudimos verificar el padrón de estudiantes. Intentá de nuevo en unos minutos." });
    }

    var completados = padron[dni];
    if (!completados) {
      return jsonResponse({ status: "dni_no_encontrado", message: "No encontramos tu DNI en el padrón de TUMO Chacarita. Verificá que esté escrito sin puntos ni espacios." });
    }

    var requisitos = comision.requisitos || [];
    if (requisitos.length > 0) {
      var cumple = requisitos.some(function (key) { return completados.indexOf(key) !== -1; });
      if (!cumple) {
        return jsonResponse({ status: "requisito_no_cumplido", message: "Para inscribirte en " + comision.taller + " necesitás: " + comision.requisitoTexto + "." });
      }
    }

    var sheet = getInscriptosSheet();
    var data = sheet.getDataRange().getValues();
    var labsDelAlumno = 0;
    var yaEnEsteLab = false;
    var inscriptosEnComision = 0;

    for (var i = 1; i < data.length; i++) {
      var rowComision = String(data[i][COL.comision] || "").trim();
      var rowLabId = CATALOGO[rowComision] ? CATALOGO[rowComision].labId : String(data[i][COL.taller]).trim().toLowerCase();
      if (normalizeDni(data[i][COL.dni]) === dni) {
        labsDelAlumno++;
        if (rowLabId === comision.labId) yaEnEsteLab = true;
      }
      if (rowComision === comisionId) inscriptosEnComision++;
    }

    if (yaEnEsteLab) {
      return jsonResponse({ status: "ya_inscripto", message: "Ya tenés una inscripción registrada en este Flash Lab." });
    }
    if (labsDelAlumno >= MAX_LABS_POR_ESTUDIANTE) {
      return jsonResponse({ status: "limite_alcanzado", message: "Ya alcanzaste el límite de " + MAX_LABS_POR_ESTUDIANTE + " Flash Labs por estudiante." });
    }
    if (inscriptosEnComision >= comision.cupo) {
      return jsonResponse({ status: "no_disponible", message: "Esta comisión ya alcanzó el cupo máximo de " + comision.cupo + " participantes." });
    }

    sheet.appendRow([new Date(), nombre, dni, correo, comision.taller, comision.dias, comision.horario, comision.disciplina, comisionId]);

    return jsonResponse({
      status: "ok",
      message: "Inscripción exitosa",
      taller: comision.taller,
      dias: comision.dias,
      horario: comision.horario,
      inscriptos: inscriptosEnComision + 1,
      maxParticipantes: comision.cupo
    });
  } catch (err) {
    console.error(err);
    return jsonResponse({ status: "error", message: "No pudimos registrar la inscripción. Intentá de nuevo en unos minutos." });
  } finally {
    lock.releaseLock();
  }
}
